alter table public.dd_demand_capture_staging add column if not exists intelligence_class text, add column if not exists advertised_price numeric, add column if not exists geography text, add column if not exists source_metadata jsonb not null default '{}'::jsonb; alter table public.dd_demand_capture_staging drop constraint if exists dd_demand_capture_staging_intelligence_class_check; alter table public.dd_demand_capture_staging add constraint dd_demand_capture_staging_intelligence_class_check check (intelligence_class is null or intelligence_class in ('BUYER_SIGNAL','COMPETITOR_SIGNAL','PROVIDER_PARTNER_SIGNAL','MARKET_PRICING_EVIDENCE','IRRELEVANT_AD')); create index if not exists dd_demand_capture_staging_intelligence_idx on public.dd_demand_capture_staging(source_type,intelligence_class,observed_at desc);
